-- Segue CRM: database changes for this release (run once; safe to run again).
--
-- Paste into the Neon SQL Editor (it runs as one transaction) or:
--   psql "$DATABASE_URL_DIRECT" -v ON_ERROR_STOP=1 -1 -f deploy/neon_upgrade_v5.sql
--
-- 1. public schema: tenant migration c3f1d2e8a901 (immutable date function for date-field indexes), only
--    if the schema is still at 4a708a753f1b. Other workspaces get it from `python -m app.cli migrate`.
-- 2. Every workspace set up for a profession:
--    * repairs labels double-renamed by the old terminology code ("Contact Person People" -> "Contact People");
--    * related lists follow the visible apps: a client shows Matters / Engagements / Loan applications
--      instead of Opportunities, Cases and Campaign History. A record type whose related lists an
--      administrator already changed is left exactly as it is;
--    * bumps the metadata revision so running API processes pick the change up without a restart.
-- No records, users or permissions are changed. Same result as `python -m app.cli refresh-domain-layouts`.
-- Generated from the application code (see backend/app/domains.py, apply_related_lists).

-- ---------------------------------------------------------------- 1. public schema at c3f1d2e8a901
DO $do$
BEGIN
  IF to_regclass('public.alembic_version') IS NOT NULL
     AND (SELECT version_num FROM public.alembic_version) = '4a708a753f1b' THEN
    CREATE OR REPLACE FUNCTION public.crm_iso_date(value text) RETURNS date
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $fn$ SELECT CASE WHEN value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN value::date END $fn$;
    UPDATE public.alembic_version SET version_num = 'c3f1d2e8a901' WHERE version_num = '4a708a753f1b';
    RAISE NOTICE 'public: migrated to c3f1d2e8a901';
  END IF;
END
$do$;

-- ---------------------------------------------------------------- 2. domain workspaces
DO $do$
