ipients_count"]}],[{"field":"campaign","label":"Enquiries","object":"lead","columns":["name","company","status"]}]],"product":[[{"field":"product","label":"Price Book Entries","object":"price_book_entry","columns":["price_book","list_price","is_active"]}],[]],"lead":[[{"field":"lead","label":"Campaign History","object":"campaign_member","columns":["campaign","status"]},{"field":"lead","label":"Consent","object":"consent","columns":["channel","status","source","captured_at"]}],[{"field":"lead","label":"Consent","object":"consent","columns":["channel","status","source","captured_at"]}]],"price_book":[[{"field":"price_book","label":"Entries","object":"price_book_entry","columns":["product","list_price","is_active"]}],[]],"quote":[[{"field":"quote","label":"Quote Lines","object":"quote_line","columns":["product","quantity","unit_price","discount","tax_amount","line_total"]}],[]],"account":[[{"field":"account","label":"Clients","object":"contact","columns":["name","title","email","phone"]},{"field":"account","label":"Opportunities","object":"opportunity","columns":["name","stage","amount","close_date"]},{"field":"account","label":"Cases","object":"case","columns":["name","subject","status","priority"]},{"field":"account","label":"Quotes","object":"quote","columns":["name","status","total","expiry_date"]},{"field":"account","label":"Invoices","object":"invoice","columns":["name","status","total","balance","due_date"]},{"field":"parent_account","label":"Child Organisations","object":"account","columns":["name","type","phone"]}],[{"field":"account","label":"Clients","object":"contact","columns":["name","title","email","phone"]},{"field":"parent_account","label":"Child Organisations","object":"account","columns":["name","type","phone"]}]],"contact":[[{"field":"primary_contact","label":"Opportunities","object":"opportunity","columns":["name","stage","amount","close_date"]},{"field":"contact","label":"Cases","object":"case","columns":["name","subject","status","priority"]},{"field":"contact","label":"Campaign History","object":"campaign_member","columns":["campaign","status"]},{"field":"contact","label":"Consent","object":"consent","columns":["channel","status","source","captured_at"]},{"field":"contact","label":"Invoices","object":"invoice","columns":["name","status","total","due_date"]}],[{"field":"primary_borrower","label":"Loan Applications (Primary Borrower)","object":"loan_application","columns":["name","loan_amount","lender","settlement_date"]},{"field":"co_borrower","label":"Loan Applications (Co-borrower)","object":"loan_application","columns":["name","primary_borrower","loan_amount","lender"]},{"field":"contact","label":"Consent","object":"consent","columns":["channel","status","source","captured_at"]}]],"invoice":[[{"field":"invoice","label":"Invoice Lines","object":"invoice_line","columns":["product","description","quantity","unit_price","discount","tax_amount","line_total"]},{"field":"invoice","label":"Payments","object":"payment","columns":["name","payment_date","amount","method","status"]}],[]],"opportunity":[[{"field":"opportunity","label":"Products","object":"opportunity_product","columns":["product","quantity","unit_price","discount","line_total"]},{"field":"opportunity","label":"Quotes","object":"quote","columns":["name","status","total","expiry_date"]},{"field":"opportunity","label":"Invoices","object":"invoice","columns":["name","status","total","balance"]}],[]]}}$spec$::jsonb;
  t record;
  item record;
  dom text;
  n integer;
  changed integer;
BEGIN
  FOR t IN SELECT schema_name, slug FROM platform.tenants WHERE status = 'active' ORDER BY created_at LOOP
    IF to_regclass(format('%I.org_settings', t.schema_name)) IS NULL THEN
      CONTINUE;
    END IF;
    EXECUTE format('SELECT value->>''domain'' FROM %I.org_settings WHERE key = ''workspace''', t.schema_name)
      INTO dom;
    IF dom IS NULL OR NOT spec ? dom THEN
      CONTINUE;
    END IF;
    changed := 0;

    -- Labels from the old two-pass rename.
    EXECUTE format('UPDATE %I.field_definitions SET label = replace(label, ''Contact Person People'', ''Contact People'') '
                   'WHERE label LIKE ''%%Contact Person People%%''', t.schema_name);
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    EXECUTE format('UPDATE %I.list_views SET name = replace(name, ''Contact Person People'', ''Contact People'') '
                   'WHERE name LIKE ''%%Contact Person People%%''', t.schema_name);
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    EXECUTE format('UPDATE %I.reports SET name = replace(name, ''Contact Person People'', ''Contact People'') '
                   'WHERE name LIKE ''%%Contact Person People%%''', t.schema_name);
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    EXECUTE format('UPDATE %I.object_definitions '
                   'SET related_lists = replace(related_lists::text, ''Contact Person People'', ''Contact People'')::jsonb '
                   'WHERE related_lists::text LIKE ''%%Contact Person People%%''', t.schema_name);
    GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;

    -- Related lists, only where they are still exactly as the old code left them.
    FOR item IN SELECT key AS api_name, value AS pair FROM jsonb_each(spec -> dom) LOOP
      EXECUTE format('UPDATE %I.object_definitions SET related_lists = $1 WHERE api_name = $2 AND related_lists = $3',
                     t.schema_name)
        USING item.pair -> 1, item.api_name, item.pair -> 0;
      GET DIAGNOSTICS n = ROW_COUNT; changed := changed + n;
    END LOOP;

    IF changed > 0 THEN
      EXECUTE format('UPDATE %I.metadata_revision SET revision = revision + 1', t.schema_name);
    END IF;
    RAISE NOTICE '%: % change(s)', coalesce(t.slug, t.schema_name), changed;
  END LOOP;
END
$do$;
